message.content:
[
  {
    "ae_shared_affect": "Seeing the fear on everyone's faces, I feel that same fear",
    "pd_harm_distress": "It makes me ache just picturing the water closing in",
    "pda_practical_counterfactual": "If we'd split into two smaller groups earlier"
  },
  {
    "ae_shared_affect": "notice the same dread creeping into me",
    "pd_harm_distress": "turns my stomach",
    "sys_consequence_reasoning": "an old man with less ahead of him than the younger ones",
    "pda_practical_counterfactual": "If the first responders had sent two boats instead of one"
  },
  {
    "ae_shared_affect": "panic in the others, and it settles into me too",
    "pd_harm_distress": "makes my chest tighten",
    "pda_practical_counterfactual": "A proper headcount before the storm hit would have"
  },
  {
    "ae_shared_affect": "fear on their faces is contagious",
    "pd_harm_distress": "gnaws at me uncomfortably",
    "sys_consequence_reasoning": "since I have no children waiting on the mainland",
    "pda_practical_counterfactual": "Had someone flagged the boat's capacity to the rescue service earlier"
  },
  {
    "ae_shared_affect": "Everyone's dread is plain, and I find it settling into me",
    "pd_harm_distress": "makes me flinch inwardly",
    "sys_consequence_reasoning": "being the strongest swimmer among us, for whatever small chance",
    "pda_practical_counterfactual": "If we'd built a signal fire the moment the storm passed"
  },
  {
    "ae_shared_affect": "notice the same unease in myself that I see on their faces",
    "pd_harm_distress": "bothers me deeply",
    "pda_practical_counterfactual": "A clearer emergency plan drawn up before the trip"
  },
  {
    "ae_shared_affect": "Their fear reads plainly, and I feel a version of it myself",
    "pd_harm_distress": "It troubles me to imagine anyone facing that rising water alone",
    "sys_consequence_reasoning": "have the fewest people depending on me at home",
    "pda_practical_counterfactual": "If the tide charts had been checked before we set out"
  },
  {
    "ae_shared_affect": "dread passing between us is something I feel too",
    "pd_harm_distress": "leaves an uneasy weight in my chest",
    "pda_responsibility": "brought us onto this island in the first place and feel responsible",
    "pda_practical_counterfactual": "A second radio call for backup transport, made hours ago"
  },
  {
    "ae_shared_affect": "sense their fear and it becomes mine as well",
    "pd_harm_distress": "is hard to sit with",
    "sys_fairness_reciprocity": "want it decided fairly rather than by nerve alone",
    "pda_practical_counterfactual": "Better coordination with the coast guard beforehand"
  },
  {
    "ae_shared_affect": "fear settles into me too",
    "pd_harm_distress": "unsettles me to think of anyone left",
    "sys_consequence_reasoning": "since I'm without family counting on my return",
    "pda_practical_counterfactual": "If the island's danger had been flagged to authorities"
  }
]
